package com.mediaservice.config;

import com.mediaservice.dao.MediaFileDAO;
import com.mediaservice.dao.MediaInstanceDAO;
import com.mediaservice.dto.MediaEntryDTO;
import com.mediaservice.enums.ContentFlag;
import com.mediaservice.model.FileReport;
import com.mediaservice.model.MediaFile;
import com.mediaservice.repository.MediaFileRepository;
import com.mediaservice.repository.MediaInstanceRepository;
import com.mediaservice.repository.ReportRepository;
import com.mediaservice.repository.ReportedFileRepository;
import com.mediaservice.service.MediaService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Configuration;

import java.util.List;
import java.util.UUID;

@Configuration
public class DatabaseSeeder implements CommandLineRunner {
    @Autowired
    private MediaService mediaService;

    @Autowired
    private MediaInstanceRepository mediaInstanceRepository;
    @Autowired
    private MediaFileRepository mediaFileRepository;
    @Autowired
    private MediaInstanceDAO mediaInstanceDAO;
    @Autowired
    private MediaFileDAO mediaFileDAO;
    @Autowired
    private ReportRepository reportRepository;
    @Autowired
    private ReportedFileRepository reportedFileRepository;

    @Override
    public void run(String... args) {
        reportedFileRepository.deleteAll();
        reportRepository.deleteAll();
        mediaFileRepository.deleteAll();
        mediaInstanceRepository.deleteAll();

        UUID owner1 = UUID.fromString("47bcba54-1b34-4971-84b5-6018b9215654");

        MediaEntryDTO mediaEntry1 = new MediaEntryDTO("data:image/png;base64,");
        MediaEntryDTO mediaEntry2 = new MediaEntryDTO("data:@file/png;base64,");

        // Create mock files
        UUID instanceId1 = mediaService.uploadMediaFile(mediaEntry1, owner1);
        UUID instanceId2 = mediaService.uploadMediaFile(mediaEntry2, owner1);
        mediaService.uploadMediaFile(mediaEntry1, owner1);
        ContentFlag contentFlag1 = ContentFlag.RISK;
        ContentFlag contentFlag2 = ContentFlag.UNASSIGNED;

        UUID fileId = mediaInstanceDAO.getMediaInstance(instanceId1).getFileId();
        MediaFile mediaFile1 = mediaFileDAO.getMediaFile(fileId);
        mediaFile1.setContentFlag(contentFlag1);
        fileId = mediaInstanceDAO.getMediaInstance(instanceId2).getFileId();
        MediaFile mediaFile2 = mediaFileDAO.getMediaFile(fileId);
        mediaFile2.setContentFlag(contentFlag2);
        mediaFileRepository.save(mediaFile1);
        mediaFileRepository.save(mediaFile2);


        UUID instanceId3 = mediaService.uploadMediaFile(mediaEntry2, owner1);

        fileId = mediaInstanceDAO.getMediaInstance(instanceId3).getFileId();
        FileReport report1 = new FileReport(owner1, fileId);
        reportRepository.save(report1);
    }
}
